INSERT INTO `projects` (`id`, `category_id`, `slug`, `title`, `short_description`, `full_description`, `location`, `hero_image`, `map_pin_top`, `map_pin_left`, `status`, `is_featured`, `show_on_map`, `sort_order`, `created_at`, `updated_at`, `total_area`, `meta_title`, `meta_description`) VALUES
  (1, 1, 'skybreez', 'Skybreez', 'Serene hillside farmhouse plots with panoramic valley views.', 'Skybreez by Grow Farms is a tranquil farmhouse community nestled in the rolling hills near Mumbai. Designed for those who seek a peaceful escape, each plot offers sweeping valley views, fresh mountain air, and a chance to reconnect with nature — while staying close to city conveniences.', 'Near Mumbai, Maharashtra', 'uploads/seed/home_banner_2.jpg', 78.7, 19.1, 'active', 0, 1, 1, '2026-09-02 12:00:00', '2026-09-02 12:00:00', NULL, NULL, NULL),
  (2, 2, 'sarasview', 'Sarasview', 'Premium plots overlooking the rocky peaks and lush canopy.', 'Sarasview by Grow Farms is a sprawling 140-acre residential farmland development located in the peaceful surroundings of Aptavane Village, just 2 km away from the historic Pali city in Maharashtra.', 'Aptavane Village, Pali, Maharashtra', 'uploads/seed/Details_Banner.jpg', 61.1, 49.4, 'active', 1, 1, 2, '2026-09-02 12:00:00', '2026-09-02 12:00:00', '140 acres', 'Sarasview — 140-acre Residential Farmland near Pali | Grow Farms', 'Scenic river-touch farmland plots at Aptavane Village, 2 km from Pali, Maharashtra. Gated, plotted and ready to own.'),
  (3, 1, 'xyzview', 'Xyzview', 'Premium plots overlooking the rocky peaks and lush canopy.', 'Xyzview offers premium farmland plots with breathtaking views of the surrounding peaks and verdant canopy. A rare opportunity to own land in one of Maharashtra\'s most scenic corridors.', 'Pali, Maharashtra', 'uploads/seed/home_banner_2.jpg', 51.4, 83.8, 'active', 0, 1, 3, '2026-09-02 12:00:00', '2026-09-02 12:00:00', NULL, NULL, NULL),
  (4, 1, 'syview-2', 'Syview 2', 'Premium plots overlooking the rocky peaks and lush canopy.', 'Syview 2 expands on the success of our first phase, offering larger plots with enhanced amenities and unobstructed views of the natural landscape.', 'Pali, Maharashtra', 'uploads/seed/home_banner_2.jpg', 78.7, 74.4, 'active', 0, 1, 4, '2026-09-02 12:00:00', '2026-09-02 12:00:00', NULL, NULL, NULL);
