INSERT INTO `travel_routes` (`id`, `project_id`, `is_active`, `mode`, `label`, `icon_image`, `description`, `sort_order`, `created_at`, `updated_at`) VALUES
  (1, 2, 1, 'road', 'By Road', 'uploads/seed/By_Road.png', 'Pali is approximately 112 kilometers away from Mumbai. You can drive by car or hire a taxi. State transport buses and private buses also operate between Mumbai and Pali.', 1, '2026-09-02 12:00:00', '2026-09-02 12:00:00'),
  (2, 2, 1, 'train', 'By Train', 'uploads/seed/By_Train.png', 'Pali is approximately 112 kilometers away from Mumbai. You can drive by car or hire a taxi. State transport buses and private buses also operate between Mumbai and Pali.', 2, '2026-09-02 12:00:00', '2026-09-02 12:00:00'),
  (3, 2, 1, 'air', 'By Air', 'uploads/seed/By_Air.png', 'Pali is approximately 112 kilometers away from Mumbai. You can drive by car or hire a taxi. State transport buses and private buses also operate between Mumbai and Pali.', 3, '2026-09-02 12:00:00', '2026-09-02 12:00:00');
INSERT INTO `buying_steps` (`id`, `is_active`, `default_open`, `rotate`, `scope`, `step_number`, `title`, `description`, `pos_top`, `pos_left`, `width`, `sort_order`, `created_at`, `updated_at`) VALUES
  (1, 1, 0, 0, 'details', '01', 'Explore Available Plots', 'Browse our curated selection of verified farmland plots across prime agricultural zones suited to your investment goals.', '22%', '57%', 236, 1, '2026-09-02 12:00:00', '2026-09-02 12:00:00'),
  (2, 1, 0, 0, 'details', '02', 'Schedule A Site Visit', 'Book a guided on-site visit with our land experts to experience the property firsthand before making any commitment.', '46%', '32%', 214, 2, '2026-09-02 12:00:00', '2026-09-02 12:00:00'),
  (3, 1, 1, -4, 'details', '03', 'Verify & Complete Documentation', 'Review all legal documents, verify the property details, and complete the purchase process securely.', '70%', '60%', 242, 3, '2026-09-02 12:00:00', '2026-09-02 12:00:00'),
  (4, 1, 0, 20, 'details', '04', 'Become A Proud Land Owner', 'Complete payment and registration to officially become a proud farmland owner and begin your agricultural journey.', '90%', '30%', 236, 4, '2026-09-02 12:00:00', '2026-09-02 12:00:00'),
  (5, 1, 0, 0, 'blog', '01', 'Choose Your Plot', 'Explore our premium agricultural land options and select the perfect location.', NULL, NULL, NULL, 1, '2026-09-02 12:00:00', '2026-09-02 12:00:00'),
  (6, 1, 0, 0, 'blog', '02', 'Visit the Site', 'Schedule a site visit with our experts to experience the project firsthand.', NULL, NULL, NULL, 2, '2026-09-02 12:00:00', '2026-09-02 12:00:00'),
  (7, 1, 0, 0, 'blog', '03', 'Complete Your Investment', 'Our team assists you throughout the documentation process, ensuring a smooth and transparent purchase.', NULL, NULL, NULL, 3, '2026-09-02 12:00:00', '2026-09-02 12:00:00');
INSERT INTO `why_pali_slides` (`id`, `is_active`, `title`, `description`, `image`, `sort_order`, `created_at`, `updated_at`) VALUES
  (1, 1, 'Smart Investment', 'Buying Farm Land In Pali Supports The Local Community. It Can Create Jobs And Help Growth.', 'uploads/seed/Why_Pali_1.png', 1, '2026-09-02 12:00:00', '2026-09-02 12:00:00'),
  (2, 1, 'Helps The Local Area', 'Buying Farm Land In Pali Supports The Local Community. It Can Create Jobs And Help Job Growth.', 'uploads/seed/Why_Pali_2.png', 2, '2026-09-02 12:00:00', '2026-09-02 12:00:00'),
  (3, 1, 'Sustainable Land', 'Every Acre In Pali Is Farmed Responsibly, Protecting Soil Health For Generations To Come.', 'uploads/seed/Why_Pali_3.png', 3, '2026-09-02 12:00:00', '2026-09-02 12:00:00'),
  (4, 1, 'Long Term Value', 'Farmland In Pali Has Steadily Appreciated, Making It A Reliable Store Of Value Over Time.', 'uploads/seed/Why_Pali_1.png', 4, '2026-09-02 12:00:00', '2026-09-02 12:00:00'),
  (5, 1, 'Trusted Partnership', 'Our Local Team Manages Every Plot Directly, So You Invest With Full Transparency.', 'uploads/seed/Why_Pali_2.png', 5, '2026-09-02 12:00:00', '2026-09-02 12:00:00');
INSERT INTO `why_choose_cards` (`id`, `project_id`, `is_active`, `position`, `title`, `body`, `image`, `alt_text`, `object_position`, `sort_order`, `created_at`, `updated_at`) VALUES
  (1, 2, 1, 'left', 'History & Culture', 'Buying farm land in Pali supports the community. It can create jobs and strengthen local heritage.', 'uploads/seed/animals.png', 'Animals in Pali farmland', 'center', 1, '2026-09-02 12:00:00', '2026-09-02 12:00:00'),
  (2, 2, 1, 'center', 'Green Environment', 'Pali offers open spaces, cleaner air, and a nature-centric lifestyle without sacrificing convenience.', 'uploads/seed/Why_Pali_1.png', 'Green farm life in Pali', 'center', 2, '2026-09-02 12:00:00', '2026-09-02 12:00:00'),
  (3, 2, 1, 'right', 'Helps The Local Area', 'Buying farm land in Pali supports the local community. It can create jobs and help the local economy.', 'uploads/seed/Why_Pali_2.png', 'Farm workers in Pali', 'center', 3, '2026-09-02 12:00:00', '2026-09-02 12:00:00');
INSERT INTO `philosophy_cards` (`id`, `is_active`, `title`, `icon_key`, `body`, `sort_order`, `created_at`, `updated_at`) VALUES
  (1, 1, 'Mission', 'mission', 'To build lasting trust with customers and stakeholders through quality products and services. We drive growth and consistency to maintain a leading market reputation.', 1, '2026-09-02 12:00:00', '2026-09-02 12:00:00'),
  (2, 1, 'Vision', 'vision', 'Cultivating a future where agricultural investment is accessible, transparent, and environmentally restorative for generations to come.', 2, '2026-09-02 12:00:00', '2026-09-02 12:00:00'),
  (3, 1, 'Values', 'values', 'Integrity in every transaction, consistency in our delivery, and an unwavering respect for the land that provides our wealth.', 3, '2026-09-02 12:00:00', '2026-09-02 12:00:00');
INSERT INTO `faqs` (`id`, `is_active`, `project_id`, `question`, `answer`, `sort_order`, `created_at`, `updated_at`) VALUES
  (1, 1, NULL, 'Can I use Spline for free?', 'Yes, totally! The Basic plan is free. You can have unlimited personal files and file viewers. Maximum 1 team project can be created with 2 team files and 2 editors. You also have access to the Spline Library and can publish your scenes with a Spline logo.', 1, '2026-09-02 12:00:00', '2026-09-02 12:00:00'),
  (2, 1, NULL, 'Why should I upgrade to Super or Super Team?', 'Upgrading gives you access to advanced features like custom domains, no Spline branding, unlimited team projects, priority support, and much more to power your professional workflow.', 2, '2026-09-02 12:00:00', '2026-09-02 12:00:00'),
  (3, 1, NULL, 'What payment methods can I use?', 'We accept all major credit and debit cards (Visa, Mastercard, Amex), as well as PayPal. All payments are securely processed and encrypted.', 3, '2026-09-02 12:00:00', '2026-09-02 12:00:00'),
  (4, 1, NULL, 'How does team billing work?', 'Team billing is calculated per seat. Each member added to your team will be charged at the same rate as your plan. You\'ll be billed at the start of each billing cycle for the total number of seats.', 4, '2026-09-02 12:00:00', '2026-09-02 12:00:00'),
  (5, 1, NULL, 'How can I cancel my subscription?', 'You can cancel your subscription at any time from your account settings under Billing. Your plan will remain active until the end of the current billing period.', 5, '2026-09-02 12:00:00', '2026-09-02 12:00:00'),
  (6, 1, NULL, 'Can I change from monthly to yearly?', 'Yes! You can switch from monthly to yearly billing at any time. The switch will take effect at the start of your next billing cycle and you\'ll enjoy a discounted annual rate.', 6, '2026-09-02 12:00:00', '2026-09-02 12:00:00'),
  (7, 1, NULL, 'How can I ask other questions about pricing?', 'Feel free to reach out to our support team via the in-app chat or email us at support@spline.design. We\'re happy to help with any pricing or billing questions.', 7, '2026-09-02 12:00:00', '2026-09-02 12:00:00'),
  (8, 1, NULL, 'Interested in Spline for Education?', 'We offer special plans for students and educators. Apply through our Education program page and get access to premium features at no cost or a significantly reduced rate.', 8, '2026-09-02 12:00:00', '2026-09-02 12:00:00');
