INSERT INTO `website_content` (`id`, `is_active`, `page`, `section_key`, `label`, `title`, `subtitle`, `sort_order`, `created_at`, `updated_at`, `link_label`, `link_url`, `body`, `image`, `extra_data`) VALUES
  (1, 1, 'home', 'hero_stage_1', 'Hero — scroll stage 1', 'Own a Piece of\nNature, Not Just Land.', 'Premium farmhouse plots designed for peaceful living, smart investment, and future generations.', 1, '2026-09-02 12:00:00', '2026-09-02 12:00:00', NULL, NULL, NULL, NULL, NULL),
  (2, 1, 'home', 'hero_stage_2', 'Hero — scroll stage 2', 'Where Serenity Meets\nSmart Investment.', 'Curated land that appreciates over time while giving you a sanctuary away from city chaos.', 2, '2026-09-02 12:00:00', '2026-09-02 12:00:00', NULL, NULL, NULL, NULL, NULL),
  (3, 1, 'home', 'hero_stage_3', 'Hero — scroll stage 3', 'Build Memories That\nOutlast Generations.', 'Lush greenery, clean air, and space to breathe — right at your doorstep, near Mumbai.', 3, '2026-09-02 12:00:00', '2026-09-02 12:00:00', NULL, NULL, NULL, NULL, NULL),
  (4, 1, 'home', 'testimonial_heading', 'Testimonial section heading', 'Testimonial', 'A place that grows in value while giving peace today.', 4, '2026-09-02 12:00:00', '2026-09-02 12:00:00', 'View All', '/testimonials', NULL, NULL, NULL),
  (5, 1, 'about', 'hero', 'About hero', 'Where Nature Meets Smart Investment', 'About GrowFarms', 1, '2026-09-02 12:00:00', '2026-09-02 12:00:00', NULL, NULL, 'We help you own premium farmland with complete transparency, expert guidance, and long-term value.', 'uploads/seed/About_Banner.png', NULL),
  (6, 1, 'about', 'trust_section', '15 Years of Cultivating Trust', '15 Years of Cultivating Trust', 'Our Legacy', 2, '2026-09-02 12:00:00', '2026-09-02 12:00:00', NULL, NULL, 'Grow Farms has a strong foothold in the market, with 15 years of experience. We guarantee reliable delivery of agricultural land, merging the grit of traditional farming with the precision of modern financial management.', 'uploads/seed/trust_img.jpg', '{\"stats\":[{\"value\":15,\"suffix\":\"+\",\"label\":\"Years Experience\"},{\"value\":7,\"suffix\":\"-8\",\"label\":\"Avg. Team Tenure\"}],\"quote\":\"Our commitment extends beyond transactions; we prioritize environmental and health considerations in every acre we manage.\",\"card_title\":\"Certified Stability\",\"card_text\":\"We understand your dream of a second home surrounded by nature.\"}'),
  (7, 1, 'about', 'philosophy_heading', 'Core Philosophy heading', 'Core Philosophy', NULL, 3, '2026-09-02 12:00:00', '2026-09-02 12:00:00', NULL, NULL, NULL, NULL, NULL),
  (8, 1, 'details', 'about_project', 'About the project', 'About Sarasview', NULL, 1, '2026-09-02 12:00:00', '2026-09-02 12:00:00', NULL, NULL, 'Sarasview by Grow Farms is a sprawling 140-acre residential farmland development located in the peaceful surroundings of Aptavane Village, just 2 km away from the historic Pali city in Maharashtra. This project provides an ideal opportunity for nature lovers and investors alike to own a piece of pristine land. It offers scenic river-touch plots, making it a perfect retreat for those who seek tranquility, yet desire modern conveniences.', 'uploads/seed/About_Img_1.png', NULL),
  (9, 1, 'details', 'facilities_heading', 'Local Facilities heading', 'Local Facilities', NULL, 2, '2026-09-02 12:00:00', '2026-09-02 12:00:00', NULL, NULL, NULL, NULL, NULL),
  (10, 1, 'details', 'invest_in_pali', 'Why should invest in Pali', 'Why should invest in Pali', NULL, 3, '2026-09-02 12:00:00', '2026-09-02 12:00:00', NULL, NULL, NULL, 'uploads/seed/newlandscapeimg.png', NULL),
